export const GUIDES=[
 {id:'fiche',title:'Lire une fiche de formation',subtitle:'Une méthode en 7 questions',items:['Qu’étudie-t-on vraiment en première année ? Relève trois enseignements et leur volume.','Quels savoirs et façons de travailler sont attendus ? Distingue critères d’examen et conseils.','Qui examine le dossier ? Quelles pièces, entretiens ou épreuves sont prévus ?','Que décrit le taux d’accès de l’an dernier ? Il ne donne pas ta probabilité personnelle.','Quel diplôme est délivré ? Vérifie sa reconnaissance et les poursuites possibles.','Quel coût total : formation, logement, transport, équipement ?','Qui contacter pour lever un doute, visiter ou demander un aménagement ?'],end:'À noter dans ton projet : ce qui te plaît, une difficulté anticipée et une question à poser.',resources:['carte','reconnaissance','data']},
 {id:'jpo',title:'Réussir une porte ouverte',subtitle:'Avant, pendant, après',items:['Avant : choisis deux formations et prépare trois questions auxquelles le site ne répond pas.','Demande un emploi du temps type et des exemples de travaux ou d’évaluations.','Parle avec un étudiant de sa semaine réelle : autonomie, fatigue, déplacements et entraide.','Renseigne-toi sur tutorat, réorientation, logement et aménagements.','Après : écris trois faits appris, une impression et une nouvelle question.','Compare tes observations avec une autre formation avant de conclure.'],end:'Une journée portes ouvertes est une rencontre, pas un concours de questions parfaites.',resources:['carte','region']},
 {id:'rencontre',title:'Rencontrer un professionnel',subtitle:'Pour découvrir un quotidien, pas seulement un métier',items:['Demande comment se déroule une journée ordinaire, pas uniquement une réussite exceptionnelle.','Quelles activités prennent le plus de temps ? Quelles contraintes sont peu connues ?','Quel parcours a-t-il suivi ? Est-ce la seule voie possible ?','Quelles qualités apprend-on avec l’expérience ?','Qu’est-ce qui lui plaît et qu’est-ce qui lui pèse ?','Relis tes notes : qu’as-tu envie de tester à ton tour ?'],end:'Respecte la confidentialité de l’échange. Tu peux citer une expérience sans enregistrer les coordonnées personnelles de la personne.',resources:['onisep','jeune']},
 {id:'motivation',title:'Écrire une motivation qui te ressemble',subtitle:'Des faits, un lien, une intention',items:['Lis la consigne de la formation : une motivation n’est demandée que dans certains dossiers. Vérifie la limite exacte.','Nomme un enseignement, un projet ou une modalité précise qui t’intéresse dans cette formation.','Relie-le à une expérience vraie : cours, lecture, engagement, visite, activité personnelle ou stage.','Explique ce que tu en as appris, pas seulement ce que tu as fait.','Formule ce que tu veux approfondir et les démarches que tu as engagées.','Relis les noms, la clarté et l’orthographe. Fais relire par un adulte, mais garde ta voix.'],end:'Le carnet te laisse écrire : il n’invente ni qualités ni expériences à ta place et ne transmet rien à Parcoursup.',resources:['carte','faq']},
 {id:'stats',title:'Des chiffres qui éclairent, pas qui décident',subtitle:'Éviter les faux raccourcis',items:['Regarde toujours l’année et le périmètre : les données ici concernent 2025, hors apprentissage.','Les candidatures en phase principale, les propositions sur la campagne et les acceptations ne mesurent pas la même chose.','Le taux d’accès publié tient compte des classements et groupes d’appel. Ce n’est pas acceptations ÷ candidatures.','Un élève peut candidater à plusieurs formations : additionner les candidats ne donne pas un nombre d’élèves différents.','Le profil des admis décrit ceux qui ont accepté. Il ne prouve pas qu’une spécialité cause la réussite.','L’académie affichée est celle de l’établissement d’accueil, pas celle d’origine de tous ses étudiants.'],end:'Pour les spécialités et moyennes des candidats admis, consulte l’outil de la fiche Parcoursup : ces variables ne figurent pas dans l’extrait open data utilisé ici.',resources:['dataset','data','carte']},
 {id:'budget',title:'Un projet possible au quotidien',subtitle:'Chiffrer pour chercher des solutions',items:['Distingue les dépenses mensuelles et les frais ponctuels de rentrée.','Chiffre logement, repas, trajets, matériel et frais de formation à partir de tarifs réels.','Identifie les ressources certaines et celles qui restent à demander. Une aide simulée n’est pas attribuée.','Prépare le DSE selon le calendrier officiel ; certaines formations sanitaires et sociales relèvent d’aides régionales.','Parle au service social si le budget risque de te faire renoncer : chercher une aide fait partie du projet.','Prévois un second scénario de logement ou de transport.'],end:'Le budget de l’application est une estimation personnelle, pas un calcul de droits. Ne saisis ni justificatif fiscal ni coordonnées bancaires.',resources:['bourses','crous','vie','region']},
 {id:'alternance',title:'Construire son projet d’apprentissage',subtitle:'Une formation et un employeur',items:['Vérifie le diplôme, le CFA, le rythme de formation et les lieux de déplacement.','Prépare une présentation courte : le métier découvert, ce que tu veux apprendre, tes disponibilités.','Organise tes contacts entreprises et tes relances sans te décourager après un silence.','Demande au CFA comment il accompagne la recherche de contrat.','Une candidature retenue sous réserve de contrat n’est pas une inscription définitivement sécurisée.','Garde une autre piste qui te plaît tant que la situation n’est pas confirmée.'],end:'Utilise les informations officielles et fais relire les conditions de ton contrat avec les interlocuteurs compétents.',resources:['alternance','jeune','faq']},
 {id:'entretien',title:'Préparer un échange avec un adulte',subtitle:'15 minutes pour repartir avec un prochain pas',items:['Commence par une phrase simple : “Aujourd’hui, j’hésite entre…” ou “Je ne sais pas encore, mais j’aime…”.','Apporte deux exemples concrets de ce que tu as aimé faire ou apprendre.','Présente une ou deux formations découvertes et les questions qui restent ouvertes.','Dis ce qui t’inquiète : méthode, distance, financement ou peur de te tromper. Tu choisis ce que tu partages.','Demande une prochaine action réaliste et un point de suivi.','Après l’entretien, note ce qui a changé dans ta compréhension.'],end:'Ton professeur principal, le Psy-EN et tes proches n’ont pas à décider à ta place : ils peuvent t’aider à voir plus clair.',resources:['conseil','avenirs']}
];

